insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-ek-101","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Electrical conductance of a solution is defined as the","options":["reciprocal of its resistance","product of resistance and cell constant","same quantity as resistivity","reciprocal of molar conductivity"],"answer_index":0,"explanation":"Conductance $G = 1/R$. A smaller resistance means the solution conducts more readily.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-102","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The SI unit used for electrical conductance is the","options":["siemens (S)","ohm ($\\Omega$)","farad (F)","tesla (T)"],"answer_index":0,"explanation":"Siemens is the reciprocal ohm. Older texts also write mho for the same unit.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-103","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Specific conductivity $\\kappa$ of an electrolyte solution is the conductance of","options":["a unit cube of the solution between opposite faces","one mole of solute placed between inert plates","the salt bridge alone","a metallic wire of the same length"],"answer_index":0,"explanation":"$\\kappa$ is intensive: it is $G$ measured for unit length and unit cross-section of solution.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-104","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The cell constant of a conductivity cell equals","options":["distance between electrodes divided by electrode area","electrode area divided by distance between electrodes","resistance multiplied by current","molar conductivity divided by $\\kappa$"],"answer_index":0,"explanation":"Cell constant $= \\ell/A$. It converts the measured conductance into specific conductivity.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-105","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Specific conductivity is obtained from the measured conductance $G$ by writing","options":["$\\kappa = G \\times (\\ell/A)$","$\\kappa = G \\times A/\\ell$","$\\kappa = G^2 \\times \\ell/A$","$\\kappa = (\\ell/A)/G$"],"answer_index":0,"explanation":"Because $G = \\kappa A/\\ell$, rearranging gives $\\kappa = G \\times$ cell constant.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-106","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Molar conductivity $\\Lambda_m$ is related to specific conductivity and molar concentration $c$ by","options":["$\\Lambda_m = \\kappa/c$","$\\Lambda_m = \\kappa \\times c$","$\\Lambda_m = c/\\kappa$","$\\Lambda_m = \\kappa + c$"],"answer_index":0,"explanation":"In SI, $\\Lambda_m = \\kappa/c$. In older cgs usage one writes $\\Lambda_m = 1000\\,\\kappa/M$ with $M$ in mol L$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-107","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"As an aqueous electrolyte is made more dilute, its specific conductivity $\\kappa$ generally","options":["falls because fewer ions occupy each cubic centimetre","rises because every ion becomes heavier","stays fixed at the value of pure water","becomes equal to $\\Lambda_m^\\circ$"],"answer_index":0,"explanation":"Dilution lowers the number of charge carriers per unit volume, so $\\kappa$ decreases even though ions may move more freely.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-108","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The usual laboratory unit of cell constant is","options":["cm$^{-1}$","S cm$^2$ mol$^{-1}$","ohm","mol L$^{-1}$"],"answer_index":0,"explanation":"$\\ell/A$ has dimensions of inverse length, so cm$^{-1}$ or m$^{-1}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-109","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a strong electrolyte such as KCl, further dilution produces","options":["only a modest further rise in $\\Lambda_m$","a sudden drop of $\\Lambda_m$ to zero","no change at all in $\\Lambda_m$","a collapse of $\\kappa$ to a negative value"],"answer_index":0,"explanation":"Strong electrolytes are already fully ionised; $\\Lambda_m$ creeps up mainly because interionic drag weakens.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-110","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Metallic conduction differs from electrolytic conduction in that metals carry current by","options":["mobile electrons, without chemical change of the conductor","migration of cations and anions that are discharged at electrodes","protons hopping through a salt bridge only","neutral solvent molecules drifting in the field"],"answer_index":0,"explanation":"A metal conducts via its electron gas. An electrolyte conducts by ion movement and is chemically changed at the electrodes.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-111","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A conductivity cell of constant $1.5\\ \\mathrm{cm^{-1}}$ reads $G = 0.020\\ \\mathrm{S}$ for a solution. The specific conductivity is","options":["$0.030\\ \\mathrm{S\\ cm^{-1}}$","$0.013\\ \\mathrm{S\\ cm^{-1}}$","$0.075\\ \\mathrm{S\\ cm^{-1}}$","$1.5\\ \\mathrm{S\\ cm^{-1}}$"],"answer_index":0,"explanation":"$\\kappa = G \\times (\\ell/A) = 0.020 \\times 1.5 = 0.030\\ \\mathrm{S\\ cm^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-112","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"If $\\kappa = 0.0050\\ \\mathrm{S\\ cm^{-1}}$ for a $0.020\\ \\mathrm{M}$ solution, $\\Lambda_m$ in S cm$^2$ mol$^{-1}$ equals","options":["250","0.25","4.0","100"],"answer_index":0,"explanation":"$\\Lambda_m = 1000\\,\\kappa/c = 1000 \\times 0.0050 / 0.020 = 250\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-113","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 0.10 M KCl standard with $\\kappa = 0.0129\\ \\mathrm{S\\ cm^{-1}}$ shows $R = 86\\ \\Omega$ in a cell. The cell constant is nearest","options":["$1.11\\ \\mathrm{cm^{-1}}$","$0.15\\ \\mathrm{cm^{-1}}$","$86\\ \\mathrm{cm^{-1}}$","$0.0129\\ \\mathrm{cm^{-1}}$"],"answer_index":0,"explanation":"$G = 1/86\\ \\mathrm{S}$, so $\\ell/A = \\kappa/G = 0.0129 \\times 86 \\approx 1.11\\ \\mathrm{cm^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-114","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Comparing $\\kappa$ and $\\Lambda_m$ as a strong electrolyte is diluted, the typical pattern is that","options":["$\\kappa$ decreases while $\\Lambda_m$ increases","both $\\kappa$ and $\\Lambda_m$ fall sharply","both $\\kappa$ and $\\Lambda_m$ rise equally","$\\Lambda_m$ falls while $\\kappa$ stays constant"],"answer_index":0,"explanation":"Fewer ions per cm$^3$ lower $\\kappa$, but each mole of electrolyte contributes more free ionic mobility, so $\\Lambda_m$ rises.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-115","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"The slight increase of $\\Lambda_m$ of NaCl on dilution is attributed mainly to","options":["weaker interionic attractions, so ions migrate faster","fresh ionisation of previously undissociated NaCl molecules","a change in the Faraday constant","conversion of NaCl into a weak electrolyte"],"answer_index":0,"explanation":"NaCl is already fully dissociated. Dilution reduces ion-atmosphere drag (Debye–Hückel–Onsager), raising molar conductivity a little.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-116","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A 0.050 M solution in a cell of constant $1.20\\ \\mathrm{cm^{-1}}$ has $R = 50\\ \\Omega$. $\\Lambda_m$ of the solute is","options":["$480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$24\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$0.48\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$","$1200\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$"],"answer_index":0,"explanation":"$\\kappa = (1/50)\\times 1.20 = 0.024\\ \\mathrm{S\\ cm^{-1}}$; then $\\Lambda_m = 1000\\times 0.024/0.050 = 480\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"hard","concept_id":"conductance","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-117","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Kohlrausch's law of independent migration states that $\\Lambda_m^\\circ$ of an electrolyte is","options":["the sum of the limiting ionic conductivities of its cation and anion","equal to the product $\\lambda_+^\\circ \\times \\lambda_-^\\circ$","independent of the identities of the two ions","measurable only for metals, not for salts"],"answer_index":0,"explanation":"At infinite dilution each ion migrates independently, so $\\Lambda_m^\\circ = \\nu_+\\lambda_+^\\circ + \\nu_-\\lambda_-^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-118","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"For a 1:1 salt MX the limiting molar conductivity may be written","options":["$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) + \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+)/\\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = \\lambda^\\circ(\\mathrm{M}^+) - \\lambda^\\circ(\\mathrm{X}^-)$","$\\Lambda_m^\\circ = 2\\lambda^\\circ(\\mathrm{M}^+)$ always"],"answer_index":0,"explanation":"One mole of MX yields one mole of each ion, so the ionic contributions simply add.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-119","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Limiting molar conductivity of a weak electrolyte such as ethanoic acid is obtained by","options":["combining $\\Lambda_m^\\circ$ values of suitable strong electrolytes, not by plotting $\\Lambda_m$ versus $\\sqrt{c}$","extrapolating a Kohlrausch $\\sqrt{c}$ graph of the weak acid itself","measuring $\\kappa$ of distilled water alone","equating $\\Lambda_m$ at 1 M to $\\Lambda_m^\\circ$"],"answer_index":0,"explanation":"A weak acid is far from fully ionised even when dilute, so the $\\sqrt{c}$ plot does not give a reliable intercept.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-120","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Degree of dissociation of a weak electrolyte is estimated from conductivities as","options":["$\\alpha = \\Lambda_m / \\Lambda_m^\\circ$","$\\alpha = \\Lambda_m^\\circ / \\Lambda_m$","$\\alpha = \\Lambda_m \\times \\Lambda_m^\\circ$","$\\alpha = \\kappa / \\Lambda_m$"],"answer_index":0,"explanation":"At a given concentration the fraction ionised is the ratio of the observed molar conductivity to the infinite-dilution value.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-121","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A practical use of Kohlrausch's law is the evaluation of","options":["$\\Lambda_m^\\circ$ of a poorly conducting weak acid from data on strong salts and acids","the Faraday constant from a copper voltameter","the order of a homogeneous reaction","the standard hydrogen electrode potential"],"answer_index":0,"explanation":"Typical combination: $\\Lambda_m^\\circ(\\mathrm{CH_3COOH}) = \\Lambda_m^\\circ(\\mathrm{CH_3COONa}) + \\Lambda_m^\\circ(\\mathrm{HCl}) - \\Lambda_m^\\circ(\\mathrm{NaCl})$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-122","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Limiting molar conductivity $\\Lambda_m^\\circ$ refers to the molar conductivity","options":["extrapolated to infinite dilution, where ions no longer hinder one another","measured in a saturated solution","of the solid crystal before it dissolves","at the boiling point of the solvent only"],"answer_index":0,"explanation":"Infinite dilution removes ion–ion interactions, so each ion contributes its characteristic $\\lambda^\\circ$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-123","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Among common aqueous ions, the unusually large $\\lambda^\\circ$ belongs to","options":["$\\mathrm{H}^+$ (and also $\\mathrm{OH}^-$)","$\\mathrm{Li}^+$ only, because it is the lightest metal ion","$\\mathrm{ClO_4}^-$ because it is bulky","every alkali-metal cation equally"],"answer_index":0,"explanation":"Grotthuss proton/hydroxide hopping through the hydrogen-bond network gives $\\mathrm{H}^+$ and $\\mathrm{OH}^-$ exceptional mobility.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-124","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"Given $\\Lambda_m^\\circ/\\mathrm{S\\ cm^2\\ mol^{-1}}$ of CH$_3$COONa = 91, HCl = 426 and NaCl = 126, $\\Lambda_m^\\circ$ of CH$_3$COOH is","options":["391","643","209","335"],"answer_index":0,"explanation":"$\\Lambda_m^\\circ(\\mathrm{HOAc}) = 91 + 426 - 126 = 391\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$ by Kohlrausch combination.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-ek-125","chapter_id":"chemistry-electrochemistry-and-chemical-kinetics","subject_id":"chemistry","stem":"A weak acid has $\\Lambda_m = 16\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$ and $\\Lambda_m^\\circ = 400\\ \\mathrm{S\\ cm^2\\ mol^{-1}}$. Its degree of dissociation is","options":["0.040","0.40","25","0.0040"],"answer_index":0,"explanation":"$\\alpha = \\Lambda_m/\\Lambda_m^\\circ = 16/400 = 0.040$.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"kohlrausch","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
    id text,
